<script setup>
import { ref, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { api, command, requestId } from '../../api/client'
import { workspace, money } from '../../services/workspace'
const router = useRouter(), products = ref([]), tables = ref([]), customers = ref([]), cart = ref([]), channel = ref('counter'), tableId = ref(''), customerId = ref(''), query = ref(''), busy = ref(false), error = ref(''), quote = ref(null)
let id = requestId()
async function menu() { error.value = ''; try { products.value = await api('/api/v1/operations/menu?branch=' + workspace.branch + '&channel=' + channel.value); cart.value = []; quote.value = null; id = requestId() } catch (e) { error.value = e.message } }
onMounted(async () => { try { await menu(); tables.value = await api('/api/v1/operations/references/tables?branch=' + workspace.branch) } catch (e) { error.value = e.message } })
function changed() { quote.value = null; id = requestId() }
function add(item) { cart.value.push({ key: requestId(), itemId: item.id, name: item.name, quantity: 1, sizeId: '', optionIds: [], note: '', variants: item.variants }); changed() }
function payload() { return { requestId: id, branchId: workspace.branch, tableId: channel.value === 'table' ? tableId.value || null : null, customerId: customerId.value || null, channel: channel.value, lines: cart.value.map(x => ({ itemId: x.itemId, quantity: Number(x.quantity), sizeId: x.sizeId || null, optionIds: x.optionIds, note: x.note })) } }
async function verify() { busy.value = true; error.value = ''; try { quote.value = await command('/quote', payload()) } catch (e) { error.value = e.message } finally { busy.value = false } }
async function save() { if (!quote.value) return; busy.value = true; error.value = ''; try { const order = await command('/orders', payload()); cart.value = []; await router.push('/app/orders?id=' + order.id) } catch (e) { error.value = e.message } finally { busy.value = false } }
async function findMember() { try { customers.value = await api('/api/v1/operations/references/customers?branch=' + workspace.branch + '&q=' + encodeURIComponent(query.value)) } catch (e) { error.value = e.message } }
</script>
<template><h1>Bán hàng tại quầy hoặc bàn</h1><p>Hãy mở ca trước. Giá được kiểm tra trên server; lưu đơn xong cần xác nhận để chuyển quầy.</p><p v-if="error" role="alert" class="error">{{ error }}</p><fieldset :disabled="busy"><div class="toolbar"><label>Kênh bán<select v-model="channel" @change="menu"><option value="counter">Tại quầy</option><option value="table">Tại bàn</option><option value="takeaway">Mang đi</option></select></label><label v-if="channel === 'table'">Bàn<select v-model="tableId" required @change="changed"><option value="">Chọn bàn</option><option v-for="t in tables" :key="t.id" :value="t.id">{{ t.code }} · {{ t.status }}</option></select></label></div>
<div class="columns"><section><div class="grid"><article v-for="p in products" :key="p.id" class="card product"><small>{{ p.category_name }}</small><h2>{{ p.name }}</h2><p>{{ p.description }}</p><p v-if="p.allergen_note" class="notice">Dị ứng: {{ p.allergen_note }}</p><p class="money">{{ money(p.price) }}</p><button @click="add(p)">Thêm món</button></article></div><p v-if="!products.length">Chưa có món đang bán có giá hiệu lực.</p></section>
<section class="card"><h2>Đơn đang soạn</h2><label>Tìm thành viên bằng mã, số điện thoại hoặc email<input v-model="query" maxlength="150"></label><button class="secondary" @click="findMember">Tìm khách</button><label>Khách hàng<select v-model="customerId" @change="changed"><option value="">Khách vãng lai G</option><option v-for="c in customers" :key="c.id" :value="c.id">{{ c.full_name }} · {{ c.member_code }}</option></select></label>
<div v-for="(line,index) in cart" :key="line.key" class="line"><h3>{{ line.name }}</h3><label>Số lượng<input v-model.number="line.quantity" type="number" min="1" max="99" @input="changed"></label><label>Kích cỡ<select v-model="line.sizeId" @change="changed"><option value="">Mặc định theo công thức</option><option v-for="v in line.variants.filter(v => v.kind === 'size')" :key="v.id" :value="v.id">{{ v.name }}</option></select></label><label v-for="v in line.variants.filter(v => v.kind !== 'size')" :key="v.id"><input v-model="line.optionIds" type="checkbox" :value="v.id" @change="changed"> {{ v.name }}</label><label>Ghi chú riêng món<input v-model="line.note" maxlength="300" @input="changed"></label><button class="secondary" @click="cart.splice(index,1);changed()">Bỏ dòng</button></div>
<p v-if="quote" class="money">Tổng theo server: {{ money(quote.total) }}</p><p v-else>Chưa chốt giá cho giỏ hiện tại.</p><div class="actions"><button :disabled="!cart.length" @click="verify">Kiểm tra giá</button><button :disabled="!quote || !cart.length" @click="save">Lưu đơn để xác nhận</button></div></section></div></fieldset></template>
